<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thanh toán thành công</title><style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f8fafc;font-family:Arial,sans-serif}.card{width:min(420px,calc(100% - 48px));padding:32px 24px;background:#fff;border:1px solid #e2e8f0;border-radius:28px;text-align:center;box-shadow:0 20px 60px rgba(15,23,42,.1)}.check{width:72px;height:72px;margin:auto;display:flex;align-items:center;justify-content:center;border-radius:50%;background:#ecfdf5;color:#059669;font-size:38px;font-weight:900}h1{margin:20px 0 8px}p{color:#64748b;line-height:1.6}.order{margin-top:22px;padding:16px;border-radius:18px;background:#f8fafc}.order span{display:block;color:#94a3b8;font-size:12px}.order strong{display:block;margin-top:6px}</style></head><body><main class="card"><div class="check">✓</div><h1>Thanh toán thành công</h1><p>Giao dịch đã được xác nhận.</p><div class="order"><span>Mã đơn hàng</span><strong>{{ $payment['order_code'] ?? '' }}</strong></div></main></body></html>